head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > P > tooltipTime]<br/>컴포넌트 영역에 마우스가 들어온 후 툴팁이 표시될때까지 기다리는 시간을 설정합니다.",
    "validation" : [        
        "tooltipDisplay 속성에 의해 툴팁이 표시되는 경우만 동작하여야 합니다.",
        "툴팁이 표시될 때까지 기다릴 시간을 초 단위 숫자로 설정할 수 있어야 합니다.",
        "값을 설정하지 않으면 1 로 적용됩니다.",
        "tooltip 속성에 의해 표시되는 툴팁에는 적용되지 않아야 합니다.",
    ]
} 



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        tooltip: "tooltip",
        tooltipDisplay: true,
        tooltipTime: con_tooltipTime.getValue(),
        tooltipShowAlways: true,
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);     

    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    strTarget += '<xf:checkcombobox ' + strNameSpace + ' ' + cList + ' ' + eList + ' style="width:200px; height:30px;">';
    strTarget += '<xf:choices>';
    strTarget += '<xf:itemset nodeset="data:dlt_Item">';
    strTarget += '<xf:label ref="label"></xf:label>';
    strTarget += '<xf:value ref="value"></xf:value>';
    strTarget += '</xf:itemset>';
    strTarget += '</xf:choices>';
    strTarget += '</xf:checkcombobox>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "checkcombobox",
        strTarget,
        grp_comp
    ); 

    target1.setValue(1);
}



scwin.target1_onclick = function (e) { 
    $c.gcm.getTooltipInfo(wf_body_bottom);
}
